import{c as e,Q as o,j as a,m as r}from"./chunks/framework.BXc4yaFE.js";const k=JSON.parse('{"title":"Auto-load Token 優化：量測腳本 + 繁中/英文比較 + 省 token 機制深研","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-06-autoload-token-optimization.md","filePath":"research/reports/2026-06-06-autoload-token-optimization.md","lastUpdated":1780842316000}'),s={name:"research/reports/2026-06-06-autoload-token-optimization.md"};function n(d,t,l,i,h,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="auto-load-token-優化-量測腳本-繁中-英文比較-省-token-機制深研" tabindex="-1">Auto-load Token 優化：量測腳本 + 繁中/英文比較 + 省 token 機制深研 <a class="header-anchor" href="#auto-load-token-優化-量測腳本-繁中-英文比較-省-token-機制深研" aria-label="Permalink to &quot;Auto-load Token 優化：量測腳本 + 繁中/英文比較 + 省 token 機制深研&quot;">​</a></h1><blockquote><p>2026-06-06 · feature/cjk-token-research 任務：(1) <code>claude -p</code> 差分量法腳本化 (2) 量現行繁中 auto-load (3) 產英文 1:1 版量測 (4) 兩版比較 (5) 深研省 token 機制 方法：tiktoken 親驗 + <code>claude -p</code> 差分（限 order-of-magnitude）+ implementer 翻譯 + researcher 機制研究 + advisor 二次攔截。 <strong>信度</strong>：[親驗]=本地實測｜[官方]=Anthropic docs｜[三方]=社群實測｜[軼事]=未實測。</p></blockquote><hr><h2 id="⚠️-方法論教訓-先講-因為它改寫了結論" tabindex="-1">⚠️ 方法論教訓（先講，因為它改寫了結論） <a class="header-anchor" href="#⚠️-方法論教訓-先講-因為它改寫了結論" aria-label="Permalink to &quot;⚠️ 方法論教訓（先講，因為它改寫了結論）&quot;">​</a></h2><p><strong><code>claude -p</code> 差分法無法精確量跨語言 token 差。</strong> 判別實驗：純英文檔（99.2% ASCII，11,217 字元）差分法報 4,475 token = <strong>2.5 chars/token</strong>，但英文真實密度 ~4。差分 <code>FULL−EMPTY</code> 被 <strong>prompt cache block 邊界 / 最小快取粒度</strong>系統性污染 ~1.7×。</p><table tabindex="0"><thead><tr><th>用途</th><th>差分法效力</th></tr></thead><tbody><tr><td>驗 <code>claude -p</code> 是否載入 CLAUDE.md（MAGIC_TOKEN 行為測試）</td><td>✅ 有效</td></tr><tr><td>auto-load 量級（數千 token）</td><td>✅ 有效</td></tr><tr><td><strong>跨語言精確比較（TC vs EN 省幾%）</strong></td><td>❌ 污染 1.7×，不可用</td></tr></tbody></table><p>→ 本報告跨語言比較<strong>改用 tiktoken o200k proxy</strong>（明確標註），精確 Claude 數需 <strong>cloud session <code>count_tokens</code></strong>（本機不可得）。</p><hr><h2 id="§1-量測腳本-scripts-measure-autoload-tokens-sh" tabindex="-1">§1 量測腳本 <code>scripts/measure-autoload-tokens.sh</code> <a class="header-anchor" href="#§1-量測腳本-scripts-measure-autoload-tokens-sh" aria-label="Permalink to &quot;§1 量測腳本 `scripts/measure-autoload-tokens.sh`&quot;">​</a></h2><p><code>claude -p &quot;hi&quot; --output-format json</code> 的 <code>usage</code> 差分（目標 vs 空 CLAUDE.md）。<strong>用途定位</strong>：量級 sanity-check 與「是否載入」驗證，<strong>非</strong>跨語言精確比較。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/measure-autoload-tokens.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # 現行 5 檔</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/measure-autoload-tokens.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> a.md</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> b.md</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 任意檔串接</span></span></code></pre></div><p>機制驗證 [親驗]：MAGIC_TOKEN 行為測試確認 <code>claude -p</code> 確實 cold-load 隔離 /tmp 目錄的 local CLAUDE.md（回應吐出注入字串）。</p><hr><h2 id="§2-繁中-vs-英文-1-1-直譯比較-o200k-proxy" tabindex="-1">§2 繁中 vs 英文 1:1 直譯比較（o200k proxy） <a class="header-anchor" href="#§2-繁中-vs-英文-1-1-直譯比較-o200k-proxy" aria-label="Permalink to &quot;§2 繁中 vs 英文 1:1 直譯比較（o200k proxy）&quot;">​</a></h2><p>implementer 產出語意 1:1 英文版（5 檔，條數逐一核對一致：bullet 37/37 等），落 <code>research/reports/2026-06-06-autoload-en/</code>，<strong>未動真實 auto-load</strong>。</p><table tabindex="0"><thead><tr><th>版本</th><th style="text-align:right;">utf-8 bytes</th><th style="text-align:right;">o200k token [親驗]</th></tr></thead><tbody><tr><td>繁中（現行）</td><td style="text-align:right;">18,726</td><td style="text-align:right;">6,038</td></tr><tr><td>英文 1:1</td><td style="text-align:right;">21,824</td><td style="text-align:right;">4,997</td></tr><tr><td><strong>差異</strong></td><td style="text-align:right;"><strong>+16.5%</strong></td><td style="text-align:right;"><strong>−17.3%（省 1,041 tok）</strong></td></tr></tbody></table><p><strong>結論（o200k proxy）</strong>：英文 1:1 直譯省 ~17% token，但<strong>多 16.5% bytes</strong>。</p><blockquote><p>⚠️ Claude 真實省幅未知且<strong>可能與 17% 不同</strong>。理論推斷（advisor）：英文 Claude≈o200k，中文 Claude≥o200k → TC→EN 在 Claude 上<strong>至少</strong>省 o200k 的 17%，可能更多。但 <code>claude -p</code> 差分污染使本機無法定論。<strong>精確值待 cloud session <code>count_tokens</code></strong>。</p></blockquote><hr><h2 id="§3-省-token-4-機制深研-roi-排序" tabindex="-1">§3 省 token 4 機制深研（ROI 排序） <a class="header-anchor" href="#§3-省-token-4-機制深研-roi-排序" aria-label="Permalink to &quot;§3 省 token 4 機制深研（ROI 排序）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>排名</th><th>機制</th><th>省幅</th><th>語意風險</th><th>信度</th></tr></thead><tbody><tr><td><strong>1</strong></td><td><strong>結構槓桿</strong>（on-demand 下沉 / 去 repo-可推導 / 合併冗餘）</td><td>30–85%</td><td>極低</td><td>[官方]</td></tr><tr><td><strong>2</strong></td><td><strong>符號/markdown 壓縮</strong>（<code>→ | !!</code> 取代散文、表格取代段落）</td><td>20–30%</td><td>低</td><td>[三方]</td></tr><tr><td><strong>3</strong></td><td><strong>Prompt caching</strong>（確保前綴穩定）</td><td>成本 −90%（非 context）</td><td>零</td><td>[官方]</td></tr><tr><td><strong>4</strong></td><td><strong>Caveman/電報式</strong>（規則本身去冠詞/贅詞）</td><td>30–50%(宣稱)</td><td><strong>高</strong></td><td>[軼事]</td></tr></tbody></table><h3 id="_3-1-結構槓桿-最高-roi-官方" tabindex="-1">3.1 結構槓桿（最高 ROI，[官方]） <a class="header-anchor" href="#_3-1-結構槓桿-最高-roi-官方" aria-label="Permalink to &quot;3.1 結構槓桿（最高 ROI，[官方]）&quot;">​</a></h3><ul><li>Anthropic 工程部落格：progressive disclosure 是 Agent Skills 核心；17 skill 名+描述 ~1,700 token，全展開需 10–15×。</li><li>Karpathy「右邊 context &gt; 更多 context」；移除「可從 repo 推導」內容（目錄/tech stack = 噪音）。</li><li>你的 workspace <strong>已有 Trigger-Index + refs/ 分層基建</strong> → 直接可用。風險極低（只搬低頻規則，高頻/安全紅線續內嵌）。</li></ul><h3 id="_3-2-符號-markdown-壓縮-三方" tabindex="-1">3.2 符號/markdown 壓縮（[三方]） <a class="header-anchor" href="#_3-2-符號-markdown-壓縮-三方" aria-label="Permalink to &quot;3.2 符號/markdown 壓縮（[三方]）&quot;">​</a></h3><ul><li>markdown 格式佔 prompt 20–30% token；表格比散文緊湊，Claude 無理解衰退。</li><li><code>→</code>（1–2 tok）&lt; &quot;leads to&quot;（3 tok）；<strong>emoji 反貴</strong>（🎯 = 3–4 tok，比常見英文詞貴 3–10×）→ 勿當語意錨點。</li></ul><h3 id="_3-3-prompt-caching-攤銷-官方-親驗-break-even" tabindex="-1">3.3 Prompt caching 攤銷（[官方]，親驗 break-even） <a class="header-anchor" href="#_3-3-prompt-caching-攤銷-官方-親驗-break-even" aria-label="Permalink to &quot;3.3 Prompt caching 攤銷（[官方]，親驗 break-even）&quot;">​</a></h3><p>[親驗] 用官方乘數驗算（write 1.25× / read 0.10× / base 1.0×）：</p><table tabindex="0"><thead><tr><th style="text-align:right;">N 次請求</th><th style="text-align:right;">無 cache</th><th style="text-align:right;">有 cache</th><th style="text-align:right;">省%</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td style="text-align:right;">1.00</td><td style="text-align:right;">1.25</td><td style="text-align:right;">−25%</td></tr><tr><td style="text-align:right;"><strong>2</strong></td><td style="text-align:right;">2.00</td><td style="text-align:right;">1.35</td><td style="text-align:right;"><strong>+32.5%（回本）</strong></td></tr><tr><td style="text-align:right;">10</td><td style="text-align:right;">10.00</td><td style="text-align:right;">2.15</td><td style="text-align:right;">78.5%</td></tr></tbody></table><p><strong>break-even = 第 2 次請求</strong>（推翻某來源「13 次」的錯誤）。<strong>但 cache 命中只省成本軸，不省 context window 格位、不影響 compliance</strong> → 壓 auto-load token 在這兩軸仍不可替代。</p><h3 id="_3-4-caveman-電報式-軼事-不建議用於規則" tabindex="-1">3.4 Caveman / 電報式（[軼事]，不建議用於規則） <a class="header-anchor" href="#_3-4-caveman-電報式-軼事-不建議用於規則" aria-label="Permalink to &quot;3.4 Caveman / 電報式（[軼事]，不建議用於規則）&quot;">​</a></h3><ul><li>社群實測 45–75% 省幅<strong>全是 output token</strong>（限制輸出簡短），非輸入端規則壓縮。</li><li>arXiv 2604.00025 的準確度提升是「限制輸出」效果，<strong>不能倒推</strong>「輸入規則電報化不衰退」。</li><li>安全紅線 / 多條件邏輯規則電報化 → 高歧義風險，零 Claude 實測背書。</li></ul><hr><h2 id="§4-給-zeuik-的最終建議優先序" tabindex="-1">§4 給 Zeuik 的最終建議優先序 <a class="header-anchor" href="#§4-給-zeuik-的最終建議優先序" aria-label="Permalink to &quot;§4 給 Zeuik 的最終建議優先序&quot;">​</a></h2><ol><li><p><strong>[P1 立即] 結構槓桿下沉</strong>：低頻細節（control-flow 表 ~250B、跨節重複）→ refs/ on-demand。Trigger-Index 已有基建，<strong>省 token 且零語意損失</strong>，是唯一無風險增量手段。走 <code>/autoload-evolution</code> 閉環。</p></li><li><p><strong>[P2] 散文→bullet/table</strong>：core.md 數個散文段轉結構化。<strong>維持繁中</strong>，改版式不改語言，省 10–20% 且 compliance 不降。</p></li><li><p><strong>[P3 免費] 確保 cache 前綴穩定</strong>：auto-load 不放動態內容（時間戳/session 狀態 → 移至 user message / <code>&lt;system-reminder&gt;</code>）。CLAUDE.md §context-management 已寫對方向。</p></li><li><p><strong>不建議</strong>：</p><ul><li><strong>語言切換英文</strong>：o200k proxy 省 17% 但多 16.5% bytes，且 Claude 真實省幅未定；<strong>更重要——若 cache 穩定命中，省的 token 邊際成本趨近 0</strong>（§3.3），語言切換的工程/合規成本不划算。守「繁中鐵律」更安全。</li><li><strong>emoji 當錨點</strong>（反增 token）／<strong>安全規則 caveman 化</strong>（高風險零背書）。</li></ul></li></ol><hr><h2 id="§5-對既有-byte-cap-紀律的修正" tabindex="-1">§5 對既有 byte-cap 紀律的修正 <a class="header-anchor" href="#§5-對既有-byte-cap-紀律的修正" aria-label="Permalink to &quot;§5 對既有 byte-cap 紀律的修正&quot;">​</a></h2><ul><li><strong>byte cap 仍是有效 proxy</strong>，但要知道它 proxy 的是「o200k token」非「Claude 真實 token」。Claude 對繁中實際更貴（§ CJK 報告 1.71×），故 19,000 byte cap 對應的 Claude 真實 token 高於 o200k 估算。</li><li><strong>真正該優化的是「結構」不是「語言」</strong>：本研究最大發現——省 token 的 ROL 排序中，<strong>語言切換墊底</strong>（風險高、cache 攤銷後收益小），<strong>結構槓桿居首</strong>（你已有基建、零風險）。</li><li>精確 Claude token 監控：待你在 <strong>cloud session</strong> 跑 <code>count_tokens</code>（<code>refs/claude-oauth-token.md</code> 有完整流程），才能把 cap 單位從「o200k proxy byte」升級到「Claude 真實 token」。</li></ul><hr><h2 id="附-產物清單" tabindex="-1">附：產物清單 <a class="header-anchor" href="#附-產物清單" aria-label="Permalink to &quot;附：產物清單&quot;">​</a></h2><ul><li><code>scripts/measure-autoload-tokens.sh</code> — 量法腳本</li><li><code>research/reports/2026-06-06-autoload-en/*.md</code> — 英文 1:1 直譯版（5 檔，候選非啟用）</li><li><code>research/reports/2026-06-06-cjk-token-tax-research.md</code> — CJK token 稅母報告（§4a-bis 已撤回差分法錯誤結論）</li></ul>',40)])])}const p=e(s,[["render",n]]);export{k as __pageData,p as default};
